?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Login · RMMC ITE</title><link rel="stylesheet" href="/assets/css/portal.css"><style>body{min-height:100vh;display:grid;place-items:center;background:linear-gradient(135deg,#fef2f2,#f8fafc)}.login-wrap{width:min(94%,980px);display:grid;grid-template-columns:1fr 1fr;background:white;border-radius:24px;overflow:hidden;box-shadow:0 16px 75px #7f1d1d16}.login-brand{background:linear-gradient(130deg,#991b1b,#5b1414);color:white;padding:65px 42px;display:flex;flex-direction:column;justify-content:center}.login-brand img{max-width:120px;max-height:115px;object-fit:contain}.login-brand h1{font-size:29px}.login-form{padding:55px 42px}.login-form h2{margin:0 0 10px;font-size:23px}.login-form p{color:#6b7280;margin-bottom:28px}.login-form .field{margin-bottom:19px}.login-form button{width:100%}.small{font-size:13px;color:#6b7280}.switch{display:flex;gap:12px;margin:14px 0 25px}.switch a{flex:1;text-align:center;text-decoration:none;padding:10px 6px;border-radius:9px;border:1px solid #e5e7eb;font-size:13px}.switch a.selected{background:#fee2e2;color:#7f1d1d;border-color:#c98989;font-weight:700}@media(max-width:750px){.login-wrap{grid-template-columns:1fr}.login-brand{padding:22px 30px}.login-brand img{width:55px}.login-brand h1{font-size:20px;margin:8px 0}.login-form{padding:30px}}</style></head><body><div class="login-wrap"><section class="login-brand"><img src="/assets/images/logo.png" alt="RMMC ITE emblem"><h1>Welcome to RMMC ITE</h1><p>Event, attendance, and clearance management — one connected portal.</p></section><section class="login-form"><h2><?= $portal === 'staff' ? 'Admin & Officer Login' : 'Student Login' ?></h2><p>Sign in using your assigned credentials.</p><div class="switch"><a href="?portal=student" class="<?=$portal==='student'?'selected':''?>">I'm a Student</a><a href="?portal=staff" class="<?=$portal==='staff'?'selected':''?>">I'm an Admin or Officer</a></div><?php if (isset($_GET['error'])): ?><div class="notice error" role="alert">Invalid credentials, account status, or selected portal.</div><?php endif; ?><?php if (isset($_GET['expired'])): ?><div class="notice">Your session expired. Please sign in again.</div><?php endif; ?><form action="/auth/authenticate.php" method="post"><input type="hidden" name="csrf" value="<?=rmmc_e(rmmc_csrf())?>"><input type="hidden" name="portal" value="<?=rmmc_e($portal)?>"><div class="field"><label for="username">Student ID or Username</label><input id="username" name="username" required maxlength="120" autocomplete="username"></div><div class="field"><label for="password">Password</label><input id="password" name="password" type="password" required autocomplete="current-password"><label class="small"><input style="width:auto" type="checkbox" id="show-password"> Show password</label></div><button type="submit">Log in</button></form><p class="small" style="margin-top:24px"><a href="/index.php">← Back to account selection</a></p></section></div><script>document.getElementById('show-password').addEventListener('change',e=>{document.getElementById('password').type=e.target.checked?'text':'password'});</script></body></html>
